Here’s a **menu-driven C++ program** demonstrating **unary (prefix and postfix increment)** and **binary (+ and <)** operator overloading — neat, complete, and lab-ready 👇  

---

### ✅ **C++ Program: Operator Overloading (Unary & Binary)**

```cpp
#include <iostream>
using namespace std;

class Number {
    int value;
public:
    // Constructor
    Number(int v = 0) { value = v; }

    // Display function
    void display() {
        cout << "Value: " << value << endl;
    }

    // Unary ++ (Prefix)
    Number operator++() {
        ++value;
        return *this;
    }

    // Unary ++ (Postfix)
    Number operator++(int) {
        Number temp = *this;
        value++;
        return temp;
    }

    // Binary + Operator
    Number operator+(const Number& n) {
        Number temp;
        temp.value = value + n.value;
        return temp;
    }

    // Binary < Operator
    bool operator<(const Number& n) {
        return value < n.value;
    }
};

int main() {
    Number n1, n2, n3;
    int choice, v1, v2;

    cout << "Enter first value: ";
    cin >> v1;
    n1 = Number(v1);

    cout << "Enter second value: ";
    cin >> v2;
    n2 = Number(v2);

    do {
        cout << "\n=== MENU ===\n";
        cout << "1. Prefix Increment (++n1)\n";
        cout << "2. Postfix Increment (n1++)\n";
        cout << "3. Add (n3 = n1 + n2)\n";
        cout << "4. Compare (n1 < n2)\n";
        cout << "5. Display Values\n";
        cout << "0. Exit\n";
        cout << "Enter your choice: ";
        cin >> choice;

        switch (choice) {
        case 1:
            ++n1;
            cout << "Prefix increment applied.\n";
            break;

        case 2:
            n1++;
            cout << "Postfix increment applied.\n";
            break;

        case 3:
            n3 = n1 + n2;
            cout << "Addition done: ";
            n3.display();
            break;

        case 4:
            if (n1 < n2)
                cout << "n1 is less than n2.\n";
            else
                cout << "n1 is not less than n2.\n";
            break;

        case 5:
            cout << "n1 -> "; n1.display();
            cout << "n2 -> "; n2.display();
            cout << "n3 -> "; n3.display();
            break;

        case 0:
            cout << "Exiting...\n";
            break;

        default:
            cout << "Invalid choice!\n";
        }
    } while (choice != 0);

    return 0;
}
```

---

### 🔍 **Explanation:**
- **Unary Operators**
  - `++n1` → Prefix: increments before use.
  - `n1++` → Postfix: increments after use.
- **Binary Operators**
  - `n1 + n2` → adds two `Number` objects.
  - `n1 < n2` → compares values, returns `true` or `false`.
- **Menu-driven:** lets you test each operator interactively.

